package com.uop.recordingtools.service;
import com.uop.recordingtools.storage.DataStore; import org.bukkit.entity.Player; import org.bukkit.plugin.java.JavaPlugin; import java.util.*;
public final class PermissionService{private final DataStore store;public PermissionService(JavaPlugin p,DataStore s){store=s;}private String base(Player p){return "permissions."+p.getUniqueId();}public void grant(Player p,String... nodes){var l=new ArrayList<>(store.data().getStringList(base(p)));for(String n:nodes){if("all".equalsIgnoreCase(n))l.add("*");else if(!l.contains(n))l.add(n);}store.set(base(p),l);store.saveNow();}public void revoke(Player p,String... nodes){var l=new ArrayList<>(store.data().getStringList(base(p)));for(String n:nodes)l.removeIf(x->x.equalsIgnoreCase(n));store.set(base(p),l);store.saveNow();}public boolean has(Player p,String node){if(p.isOp())return true;for(String x:store.data().getStringList(base(p))){if(x.equals("*")||x.equalsIgnoreCase(node)||(x.endsWith(".*")&&node.startsWith(x.substring(0,x.length()-1))))return true;}return false;}public List<String> list(Player p){return store.data().getStringList(base(p));}public void reset(Player p,String node){if(node==null)store.remove(base(p));else{var l=new ArrayList<>(list(p));l.removeIf(x->x.equalsIgnoreCase(node));store.set(base(p),l);}store.saveNow();}}
